body {
  margin: 0;
  padding: 16px;
  box-sizing: border-box;
  background: #0b1d16;
  color: #e6f5ec;
  font-family: system-ui, sans-serif;
}
.scene {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.step-label {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #a7ce65;
}
.flow {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 6px;
  min-height: 104px;
}
.node {
  flex: 1 1 0;
  min-width: 0;
  padding: 10px 8px;
  border-radius: 12px;
  border: 1px solid #1db584;
  background: rgba(29, 181, 132, 0.12);
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  gap: 4px;
  animation: pop 0.35s ease both;
}
.node-title {
  font-size: 13px;
  font-weight: 800;
  color: #e6f5ec;
}
.node-sub {
  font-size: 11px;
  line-height: 1.35;
  color: #c9dccf;
}
.node.pred {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.14);
}
.node.pred .node-title {
  color: #7dd3fc;
}
.node.actual {
  border-color: #e2b44a;
  background: rgba(226, 180, 74, 0.14);
}
.node.actual .node-title {
  color: #f0cf7a;
}
.arrow {
  flex: 0 0 auto;
  align-self: center;
  font-size: 22px;
  font-weight: 800;
  color: #a7ce65;
  animation: pop 0.35s ease both;
}
@keyframes pop {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}
.match {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid #4fd8a8;
  background: rgba(79, 216, 168, 0.1);
  text-align: center;
}
.match.on {
  display: flex;
  animation: pop 0.4s ease both;
}
.match-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
}
.match-pred { color: #7dd3fc; }
.match-actual { color: #f0cf7a; }
.match-eq { color: #4fd8a8; font-size: 16px; }
.match-title {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: #4fd8a8;
}
.match-text {
  font-size: 12px;
  color: #e6f5ec;
}
.caption {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: #c9dccf;
  min-height: 40px;
}

/* ── explanation panel (shared by every generated ML animation) ── */
.explain {
  box-sizing: border-box;
  max-width: 640px;
  margin-top: 4px;
  padding: 14px 18px 16px;
  min-height: 150px;
  border-radius: 12px;
  background: rgba(29, 181, 132, 0.10);
  border: 1px solid rgba(29, 181, 132, 0.45);
  border-left: 5px solid #1db584;
}
.explain-h {
  margin: 0 0 8px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #a7ce65;
}
.explain-t {
  margin: 0;
  font-size: 16px;
  line-height: 1.55;
  color: #f1faf4;
}
.explain-t strong {
  font-weight: 800;
  color: #ffd98a;
}

